window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ad8535477782c40f"]={"versions": [{"id": "FIG-ad8535477782c40f", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm mit Schnittstellen- und Realisierungsbeziehungen, annotiert mit Stereotypen des AUTOSAR Adaptive Platform (AAP) Profils.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP Release R23-11), Funktionsbereich <em>Intrusion Detection System</em> (IDS).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der standardisierten Schnittstelle zur Meldung sicherheitsrelevanter Ereignisse (Security Events) von einer Anwendung an den zentralen <em>Intrusion Detection System Manager</em> (IdsM). Das Muster realisiert eine lose Kopplung zwischen Event-Detektoren (Sensoren) und der zentralen Sicherheits-Überwachungsinstanz.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Adaptive Application</code></strong> (UML-Komponente):</li>\n<li>Repräsentiert einen Prozess im User-Space der Adaptive Platform, der als Security-Event-Sensor fungiert (z. B. Diagnose, Firewall, Routing-Engine).</li>\n<li><strong><code>«aapPortInterface,aapAPI» EventReporter</code></strong> (UML-Interface):</li>\n<li><strong>Stereotypen:</strong></li>\n<li><code>«aapPortInterface»</code>: Modellierungselement im AUTOSAR-Metamodell für Port-basierte Dienstarchitekturen.</li>\n<li><code>«aapAPI»</code>: Direkte Repräsentation als C++ Programmierschnittstelle (<code>ara::idsm::EventReporter</code>).</li>\n<li><strong>Operationen:</strong> <code>+ ReportEvent()</code>: Öffentliche Methode zum Übermitteln von Security Events inklusive Event-ID und optionalen Kontextdaten (Payload).</li>\n<li><strong><code>«aapFunctionalCluster» Intrusion Detection System Manager</code></strong> (UML-Komponente):</li>\n<li><strong>Stereotyp:</strong> <code>«aapFunctionalCluster»</code>: Standardisierter Kernbestandteil der Adaptive Platform Architecture.</li>\n<li><strong>Realisierungsform:</strong> <code>daemon-based</code>: Läuft als eigenständiger System-Daemon/Dienstprozess auf OS-Ebene.</li>\n<li><strong>Beziehungen:</strong></li>\n<li><code>Adaptive Application</code> $\\xrightarrow{«use»}$ <code>EventReporter</code>: Abhängigkeitsbeziehung (Client-Nutzung).</li>\n<li><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>EventReporter</code>: Schnittstellen-Realisierung (<code>Interface Realization</code>). Der Daemon implementiert das Interface serverseitig bzw. stellt die Backend-Implementierung bereit.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Eine <code>Adaptive Application</code> registriert zur Laufzeit ein sicherheitskritisches Vorkommnis (z. B. fehlgeschlagene Authentifizierung, Integritätsverletzung, CAN/Ethernet-Frame-Anomalie).</li>\n<li><strong>Synchroner API-Aufruf:</strong> Die Applikation ruft die lokale Methode <code>ReportEvent()</code> der Client-Bibliothek (<code>ara::idsm</code>) auf.</li>\n<li><strong>IPC-Transport:</strong> Da der <code>Intrusion Detection System Manager</code> als <em>daemon-based</em> deklariert ist, wird das Ereignis über einen Inter-Process-Communication-Kanal (IPC, z. B. Unix Domain Sockets oder POSIX Message Queues/Shared Memory) asynchron oder non-blocking in den Adressraum des IdsM-Daemons übertragen.</li>\n<li><strong>Daemon-Verarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierung und Filterung (z. B. Rate Limiting, Thresholding gegen Event-Flooding/DoS).</li>\n<li>Aggregation qualifizierter Security Events (QsEv) und Weiterleitung an den IdsM-Kanal (z. B. Persistenzspeicher oder On-Board/Off-Board Reporting via IdsR an ein Vehicle Security Operations Center).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rückmeldung:</strong> Typischerweise Rückgabe eines <code>ara::core::Result&lt;void&gt;</code> an die aufrufende Applikation (bestätigt die Pufferung der IPC-Nachricht; kein Warten auf Off-Board-Versand).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API- und Manifest-Vertrag:</strong></li>\n<li>Entwickler einer <code>Adaptive Application</code> müssen in den ARXML-Beschreibungen (Application Design / Execution Manifest) die Service-Instanz-Abhängigkeit zum <code>EventReporter</code>-Port definieren.</li>\n<li>Die Security-Event-IDs müssen mit der IdsM-Konfiguration des Gesamtfahrzeugs harmonisiert sein (IDs, Context Data Types).</li>\n<li><strong>IAM / Access Control:</strong></li>\n<li>Der Zugriff auf die <code>EventReporter</code>-API erfordert entsprechende Berechtigungen im Identity and Access Management (IAM), um Spoofing von Security-Events durch unprivilegierte Prozesse zu verhindern.</li>\n<li><strong>Laufzeit- und Echtzeitverhalten:</strong></li>\n<li><code>ReportEvent()</code> muss reentrancy- und thread-safe sein.</li>\n<li>Die API ist so implementiert, dass Event-Flooding die Echtzeitpfade der anwendenden Applikation nicht blockiert; bei IPC-Pufferüberlauf greifen definierte Drop-Strategien.</li>\n<li>Entwickler dürfen keine sensiblen Klartextdaten (Schlüssel, Passwörter, PII) in den Kontext-Payloads von <code>ReportEvent()</code> übermitteln.</li>\n</ul>"}, {"id": "FIG-7126de56b9fa299d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm mit Schnittstellen- und Realisierungsbeziehungen, annotiert mit Stereotypen des AUTOSAR Adaptive Platform (AAP) Profils.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP Release R24-11), Funktionsbereich <em>Intrusion Detection System</em> (IDS).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der standardisierten Schnittstellen zur Meldung sicherheitsrelevanter Ereignisse (<code>EventReporter</code>) sowie zur Steuerung und Abfrage des Reporting-Modus (<code>ReportingModeProvider</code>) zwischen einer <code>Adaptive Application</code> und dem zentralen <code>Intrusion Detection System Manager</code> (IdsM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Adaptive Application</code></strong> (UML-Komponente):</li>\n<li>Repräsentiert einen Prozess im User-Space der Adaptive Platform, der als Security-Event-Sensor fungiert und über Ports auf die IdsM-Schnittstellen zugreift.</li>\n<li><strong><code>«aapPortInterface,aapAPI» EventReporter</code></strong> (UML-Interface):</li>\n<li><strong>Stereotypen:</strong> <code>«aapPortInterface»</code>, <code>«aapAPI»</code> (C++ Programmierschnittstelle <code>ara::idsm::EventReporter</code>).</li>\n<li><strong>Operationen:</strong> <code>+ ReportEvent()</code>: Öffentliche Methode zum Übermitteln von Security Events inklusive Event-ID und optionaler Kontextdaten.</li>\n<li><strong><code>«aapAPI,aapPortInterface» ReportingModeProvider</code></strong> (UML-Interface):</li>\n<li><strong>Stereotypen:</strong> <code>«aapAPI»</code>, <code>«aapPortInterface»</code> (C++ Programmierschnittstelle <code>ara::idsm::ReportingModeProvider</code>).</li>\n<li><strong>Operationen:</strong></li>\n<li><code>+ GetReportingMode()</code>: Öffentliche Methode zur Abfrage des aktuellen Reporting-Modus des IdsM.</li>\n<li><code>+ SetReportingMode()</code>: Öffentliche Methode zum Konfigurieren bzw. Umschalten des Reporting-Modus.</li>\n<li><strong><code>«aapFunctionalCluster» Intrusion Detection System Manager</code></strong> (UML-Komponente):</li>\n<li><strong>Stereotyp:</strong> <code>«aapFunctionalCluster»</code>: Standardisierter Kernbestandteil der Adaptive Platform Architecture.</li>\n<li><strong>Realisierungsform:</strong> <code>daemon-based</code>: Läuft als eigenständiger System-Daemon/Dienstprozess auf OS-Ebene.</li>\n<li><strong>Beziehungen:</strong></li>\n<li><code>Adaptive Application</code> $\\xrightarrow{«use»}$ <code>EventReporter</code>: Abhängigkeitsbeziehung (Client-Nutzung zum Melden von Events).</li>\n<li><code>Adaptive Application</code> $\\xrightarrow{«use»}$ <code>ReportingModeProvider</code>: Abhängigkeitsbeziehung (Client-Nutzung zur Abfrage und Steuerung des Reporting-Modus).</li>\n<li><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>EventReporter</code>: Schnittstellen-Realisierung durch den IdsM-Daemon.</li>\n<li><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>ReportingModeProvider</code>: Schnittstellen-Realisierung durch den IdsM-Daemon.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Modusverwaltung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine autorisierte <code>Adaptive Application</code> kann über <code>GetReportingMode()</code> den aktuellen Überwachungszustand des IdsM abfragen bzw. mittels <code>SetReportingMode()</code> den aktiven Reporting-Modus steuern (z. B. Aktivierung/Deaktivierung bestimmter Reporting-Klassen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Security-Event-Trigger:</strong> Eine <code>Adaptive Application</code> erkennt zur Laufzeit ein sicherheitskritisches Ereignis.</li>\n<li><strong>Synchroner API-Aufruf:</strong> Die Applikation ruft <code>ReportEvent()</code> der Client-Bibliothek (<code>ara::idsm</code>) auf.</li>\n<li><strong>IPC-Transport:</strong> Die Aufrufe beider Schnittstellen (<code>EventReporter</code>, <code>ReportingModeProvider</code>) werden über Inter-Process-Communication an den daemon-basierten <code>Intrusion Detection System Manager</code> übertragen.</li>\n<li><strong>Daemon-Verarbeitung:</strong> Der IdsM-Daemon verarbeitet Moduskonfigurationen und filtert/aggregiert gemeldete Security Events gemäß den aktiven Filter- und Reporting-Regeln.</li>\n<li><strong>Rückmeldung:</strong> Beide Schnittstellen bestätigen die Entgegennahme der Anfragen über Standard-Rückgabetypen (<code>ara::core::Result</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API- und Manifest-Vertrag:</strong></li>\n<li>Entwickler einer <code>Adaptive Application</code> müssen in den ARXML-Modellen (Application Design / Execution Manifest) Service-Ports für <code>EventReporter</code> und gegebenenfalls <code>ReportingModeProvider</code> konfigurieren und an die entsprechenden IdsM-Instanzen binden.</li>\n<li><strong>Zugriffskontrolle & Privilegien:</strong></li>\n<li>Während das Melden von Ereignissen (<code>EventReporter</code>) typischerweise breiter gestreut für überwachte Applikationen zugänglich ist, erfordert die Modus-Steuerung (<code>SetReportingMode()</code>) restriktive Berechtigungen (z. B. Identity and Access Management / IAM), um unbefugtes Deaktivieren oder Manipulieren des IDS-Monitorings zu unterbinden.</li>\n<li><strong>Architektur-Entkopplung:</strong></li>\n<li>Die Aufteilung in zwei funktionale Interfaces trennt administrative Steuerungsaufgaben sauber vom kontinuierlichen Sensor-Reporting, während die daemon-basierte Architektur eine robuste, nicht-blockierende Ausführung sicherstellt.</li>\n</ul>"}, {"id": "FIG-b07d62866897deec", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm mit Schnittstellen- und Realisierungsbeziehungen, annotiert mit Stereotypen des AUTOSAR Adaptive Platform (AAP) Profils.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP Release R24-11), Funktionsbereich <em>Intrusion Detection System</em> (IDS).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der standardisierten Schnittstellen zur Meldung sicherheitsrelevanter Ereignisse (<code>EventReporter</code>) sowie zur Steuerung und Abfrage des Reporting-Modus (<code>ReportingModeProvider</code>) zwischen einer <code>Adaptive Application</code> und dem zentralen <code>Intrusion Detection System Manager</code> (IdsM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Adaptive Application</code></strong> (UML-Komponente):</li>\n<li>Repräsentiert einen Prozess im User-Space der Adaptive Platform, der als Security-Event-Sensor fungiert und über Ports auf die IdsM-Schnittstellen zugreift.</li>\n<li><strong><code>«aapPortInterface,aapAPI» EventReporter</code></strong> (UML-Interface):</li>\n<li><strong>Stereotypen:</strong> <code>«aapPortInterface»</code>, <code>«aapAPI»</code> (C++ Programmierschnittstelle <code>ara::idsm::EventReporter</code>).</li>\n<li><strong>Operationen:</strong> <code>+ ReportEvent()</code>: Öffentliche Methode zum Übermitteln von Security Events inklusive Event-ID und optionaler Kontextdaten.</li>\n<li><strong><code>«aapAPI,aapPortInterface» ReportingModeProvider</code></strong> (UML-Interface):</li>\n<li><strong>Stereotypen:</strong> <code>«aapAPI»</code>, <code>«aapPortInterface»</code> (C++ Programmierschnittstelle <code>ara::idsm::ReportingModeProvider</code>).</li>\n<li><strong>Operationen:</strong></li>\n<li><code>+ GetReportingMode()</code>: Öffentliche Methode zur Abfrage des aktuellen Reporting-Modus des IdsM.</li>\n<li><code>+ SetReportingMode()</code>: Öffentliche Methode zum Konfigurieren bzw. Umschalten des Reporting-Modus.</li>\n<li><strong><code>«aapFunctionalCluster» Intrusion Detection System Manager</code></strong> (UML-Komponente):</li>\n<li><strong>Stereotyp:</strong> <code>«aapFunctionalCluster»</code>: Standardisierter Kernbestandteil der Adaptive Platform Architecture.</li>\n<li><strong>Realisierungsform:</strong> <code>daemon-based</code>: Läuft als eigenständiger System-Daemon/Dienstprozess auf OS-Ebene.</li>\n<li><strong>Beziehungen:</strong></li>\n<li><code>Adaptive Application</code> $\\xrightarrow{«use»}$ <code>EventReporter</code>: Abhängigkeitsbeziehung (Client-Nutzung zum Melden von Events).</li>\n<li><code>Adaptive Application</code> $\\xrightarrow{«use»}$ <code>ReportingModeProvider</code>: Abhängigkeitsbeziehung (Client-Nutzung zur Abfrage und Steuerung des Reporting-Modus).</li>\n<li><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>EventReporter</code>: Schnittstellen-Realisierung durch den IdsM-Daemon.</li>\n<li><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>ReportingModeProvider</code>: Schnittstellen-Realisierung durch den IdsM-Daemon.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Modusverwaltung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine autorisierte <code>Adaptive Application</code> kann über <code>GetReportingMode()</code> den aktuellen Überwachungszustand des IdsM abfragen bzw. mittels <code>SetReportingMode()</code> den aktiven Reporting-Modus steuern (z. B. Aktivierung/Deaktivierung bestimmter Reporting-Klassen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Security-Event-Trigger:</strong> Eine <code>Adaptive Application</code> erkennt zur Laufzeit ein sicherheitskritisches Ereignis.</li>\n<li><strong>Synchroner API-Aufruf:</strong> Die Applikation ruft <code>ReportEvent()</code> der Client-Bibliothek (<code>ara::idsm</code>) auf.</li>\n<li><strong>IPC-Transport:</strong> Die Aufrufe beider Schnittstellen (<code>EventReporter</code>, <code>ReportingModeProvider</code>) werden über Inter-Process-Communication an den daemon-basierten <code>Intrusion Detection System Manager</code> übertragen.</li>\n<li><strong>Daemon-Verarbeitung:</strong> Der IdsM-Daemon verarbeitet Moduskonfigurationen und filtert/aggregiert gemeldete Security Events gemäß den aktiven Filter- und Reporting-Regeln.</li>\n<li><strong>Rückmeldung:</strong> Beide Schnittstellen bestätigen die Entgegennahme der Anfragen über Standard-Rückgabetypen (<code>ara::core::Result</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API- und Manifest-Vertrag:</strong></li>\n<li>Entwickler einer <code>Adaptive Application</code> müssen in den ARXML-Modellen (Application Design / Execution Manifest) Service-Ports für <code>EventReporter</code> und gegebenenfalls <code>ReportingModeProvider</code> konfigurieren und an die entsprechenden IdsM-Instanzen binden.</li>\n<li><strong>Zugriffskontrolle & Privilegien:</strong></li>\n<li>Während das Melden von Ereignissen (<code>EventReporter</code>) typischerweise breiter gestreut für überwachte Applikationen zugänglich ist, erfordert die Modus-Steuerung (<code>SetReportingMode()</code>) restriktive Berechtigungen (z. B. Identity and Access Management / IAM), um unbefugtes Deaktivieren oder Manipulieren des IDS-Monitorings zu unterbinden.</li>\n<li><strong>Architektur-Entkopplung:</strong></li>\n<li>Die Aufteilung in zwei funktionale Interfaces trennt administrative Steuerungsaufgaben sauber vom kontinuierlichen Sensor-Reporting, während die daemon-basierte Architektur eine robuste, nicht-blockierende Ausführung sicherstellt.</li>\n</ul>"}], "trans": [{"from": "FIG-ad8535477782c40f", "to": "FIG-7126de56b9fa299d", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong><code>ReportingModeProvider</code> (Interface):</strong> Neues Interface mit den Stereotypen <code>«aapAPI,aapPortInterface»</code> und den Operationen <code>+ GetReportingMode()</code> sowie <code>+ SetReportingMode()</code> hinzugefügt.</li>\n<li><strong><code>Adaptive Application</code> $\\rightarrow$ <code>ReportingModeProvider</code> (Abhängigkeit):</strong> Neue <code>«use»</code>-Beziehung von der Applikation auf das Interface ergänzt.</li>\n<li><strong><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>ReportingModeProvider</code> (Realisierung):</strong> Neue Schnittstellen-Realisierungsbeziehung vom IdsM-Cluster auf das Interface ergänzt.</li>\n<li><strong><code>Adaptive Application</code> (Komponente):</strong> Horizontale Verbreiterung der Komponente zur visuellen Abdeckung beider Schnittstellen.</li>\n</ul>"}, {"from": "FIG-7126de56b9fa299d", "to": "FIG-b07d62866897deec", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
